package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.convert.FromString;
import org.joda.time.base.BasePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Period_normalizedStandard_TriageGen1Test {

    @Test
    public void testNormalizedStandard_StandardType() {
        // Test with a standard period: 1 year, 13 months, 1 week, 2 days, 3 hours, 4 mins, 5 secs, 6 millis
        // The logic should normalize 13 months into 1 year and 1 month.
        // Total years: 1 + (13/12) = 2. Total months: 13 % 12 = 1.
        Period period = new Period(1, 13, 1, 2, 3, 4, 5, 6, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.standard());

        assertEquals(2, result.getYears());
        assertEquals(1, result.getMonths());
        assertEquals(1, result.getWeeks());
        assertEquals(2, result.getDays());
        assertEquals(3, result.getHours());
        assertEquals(4, result.getMinutes());
        assertEquals(5, result.getSeconds());
        assertEquals(6, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_NoYearsOrMonths() {
        // Test case where years and months are 0 to cover the 'if (years != 0 || months != 0)' branch
        Period period = new Period(0, 0, 1, 2, 3, 4, 5, 6, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.standard());

        assertEquals(0, result.getYears());
        assertEquals(0, result.getMonths());
        assertEquals(1, result.getWeeks());
        assertEquals(2, result.getDays());
        assertEquals(3, result.getHours());
        assertEquals(4, result.getMinutes());
        assertEquals(5, result.getSeconds());
        assertEquals(6, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_OnlyYears() {
        // Test case where years != 0 but months == 0
        Period period = new Period(1, 0, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.standard());

        assertEquals(1, result.getYears());
        assertEquals(0, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_OnlyMonths() {
        // Test case where months != 0 but years == 0
        Period period = new Period(0, 13, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.standard());

        assertEquals(1, result.getYears());
        assertEquals(1, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_NegativeValues() {
        // Test with negative values to ensure math consistency
        // -13 months -> -1 year and -1 month. 
        // years = -1 + (-13/12) = -1 + (-1) = -2.
        // months = -13 % 12 = -1.
        Period period = new Period(0, -13, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.standard());

        assertEquals(-2, result.getYears());
        assertEquals(-1, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_DifferentPeriodType() {
        // Test that the passed PeriodType is applied to the result
        Period period = new Period(1, 0, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        // Using a type that only includes days and hours
        PeriodType customType = new PeriodType(false, false, false, true, true, true, true, true);
        Period result = period.normalizedStandard(customType);

        // Even if we pass years, if the type doesn't support years, 
        // the result's internal representation based on millis will be converted to the type.
        // However, the code calls result.withYears(years) which might re-inject it if the type allows.
        // In Joda, if the type doesn't support a field, withField usually returns same or ignores.
        // Let's test with a type that supports years but is different from standard.
        PeriodType typeWithYears = PeriodType.of(PeriodType.YEARS, PeriodType.MONTHS, PeriodType.DAYS);
        Period result2 = period.normalizedStandard(typeWithYears);

        assertNotNull(result2);
        assertEquals(typeWithYears, result2.getPeriodType());
    }

    @Test
    public void testNormalizedStandard_LargeMillis() {
        // Test the long overflow protection (though the comment says it won't happen)
        // 10000 days is a large number of millis
        Period period = new Period(10000, 0, 0, 0, 0, 0, 0, 0, PeriodType.standard());
        Period result = period.normalizedStandard(PeriodType.standard());

        // 10000 days is roughly 27 years.
        // The logic calculates millis first, then applies years/months.
        // Result should still represent the same duration.
        assertTrue(result.getMillis() >= 0);
        assertEquals(10000, result.getDays() + (result.getWeeks() * 7)); 
        // Note: exact day count might vary due to how Period handles weeks/days, 
        // but the total duration in millis should be preserved.
    }
}
